"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

interface NavigationProps {
  isFormationsOpen: boolean;
  setIsFormationsOpen: (isOpen: boolean) => void;
}

export default function Navigation({
  isFormationsOpen,
  setIsFormationsOpen,
}: NavigationProps) {
  const pathname = usePathname();

  const isFormationsActive = pathname.startsWith("/formations");
  const isNousRejoindreActive = pathname === "/nous-rejoindre";

  return (
    <nav className="flex items-center space-x-8">
      {/* Formations Link avec Dropdown */}
      <div className="relative">
        <button
          onClick={() => setIsFormationsOpen(!isFormationsOpen)}
          className={`flex cursor-pointer items-center space-x-1 px-4 py-2 rounded-full font-satoshi font-medium transition-all duration-300 ${
            isFormationsOpen || isFormationsActive
              ? "bg-primary text-white"
              : "text-grayBlue hover:bg-primary/10 hover:text-primary"
          }`}
        >
          <span>Formations</span>
          <svg
            className={`w-4 h-4 transition-transform duration-200 ${
              isFormationsOpen ? "rotate-180" : ""
            }`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 9l-7 7-7-7"
            />
          </svg>
        </button>
      </div>

      {/* À propos */}
      <Link
        href="/nous-rejoindre"
        className={`px-4 py-2 rounded-full font-satoshi font-medium transition-all duration-300 ${
          isNousRejoindreActive
            ? "bg-primary text-white"
            : "text-grayBlue hover:bg-primary/10 hover:text-primary"
        }`}
      >
        Nous rejoindre
      </Link>
    </nav>
  );
}
